/**
 * lib/chat/stickers.ts — Ledger Chat's own sticker packs.
 *
 * Every sticker is drawn for the app (public/stickers/<pack>/<id>.svg, generated by
 * scripts/stickers/build.ts from the character rig in scripts/stickers/art.ts): no third-party
 * artwork. A sticker travels as the message text `__STICKER__img:<pack>/<id>`; the receiver renders
 * the picture from this site only, so a message can never make the client load an arbitrary URL.
 *
 * `scene` is the full-chat moment a sticker plays when it arrives or is tapped
 * (lib/chat/sticker-scenes.ts, about 4.5 s), like the screen effects of iMessage. `tint` colours the
 * scene's paint (splats, glow) when it should match the sticker.
 */

export type StickerScene =
  | 'hearts' | 'kiss' | 'hug' | 'sunrise' | 'night' | 'rain' | 'shake' | 'confetti' | 'fireworks'
  | 'sparkle' | 'splat' | 'melt' | 'boom' | 'money' | 'fire' | 'dash' | 'cool' | 'bubbles' | 'jelly';

export const STICKER_SCENES: readonly StickerScene[] = [
  'hearts', 'kiss', 'hug', 'sunrise', 'night', 'rain', 'shake', 'confetti', 'fireworks',
  'sparkle', 'splat', 'melt', 'boom', 'money', 'fire', 'dash', 'cool', 'bubbles', 'jelly',
];

export interface Sticker {
  id: string;
  label: string;
  scene?: StickerScene;
  /** Paint colour for the scene (#rrggbb). */
  tint?: string;
}

export interface StickerPack {
  id: string;
  name: string;
  description: string;
  /** The sticker shown on the pack's tab. */
  cover: string;
  accent: string;
  stickers: Sticker[];
}

